DROP VIEW IF EXISTS `Sales by Category`;
CREATE VIEW `Sales by Category` AS
select `northwind`.`Categories`.`CategoryID` AS `CategoryID`,`northwind`.`Categories`.`CategoryName` AS `CategoryName`,`northwind`.`Products`.`ProductName` AS `ProductName`,sum(`northwind`.`Order Details Extended`.`ExtendedPrice`) AS `ProductSales` from (`northwind`.`Categories` join (`northwind`.`Products` join (`northwind`.`Orders` join `northwind`.`Order Details Extended` on((`northwind`.`Orders`.`OrderID` = `northwind`.`Order Details Extended`.`OrderID`))) on((`northwind`.`Products`.`ProductID` = `northwind`.`Order Details Extended`.`ProductID`))) on((`northwind`.`Categories`.`CategoryID` = `northwind`.`Products`.`CategoryID`))) where (`northwind`.`Orders`.`OrderDate` between '1997-01-01' and '1997-12-31') group by `northwind`.`Categories`.`CategoryID`,`northwind`.`Categories`.`CategoryName`,`northwind`.`Products`.`ProductName`